68	// Binary min-heap ordered by (expiresAt, insertion order). Expiry heaps are
69	// used three ways: one global heap drives reclamation, each resource gets one
70	// for lazy capacity accounting, and each quota node gets one for lazy quota
71	// accounting. Renewals push fresh nodes and retire the old ones, so reclaiming
72	// expired leases only walks entries that are actually due instead of scanning
73	// the whole table.
74	class ExpiryQueue {
75	  constructor() {
76	    this.nodes = [];
77	  }
78	
79	  get size() {
80	    return this.nodes.length;
81	  }
82	
83	  push(node) {
84	    const nodes = this.nodes;
85	    nodes.push(node);
86	    let i = nodes.length - 1;
87	    while (i > 0) {
88	      const parent = (i - 1) >> 1;
89	      if (expiresBefore(nodes[i], nodes[parent])) {
90	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
91	        i = parent;
92	      } else {
93	        break;
94	      }
95	    }
96	  }
97	
98	  peek() {
99	    return this.nodes[0];
100	  }
101	
102	  pop() {
103	    const nodes = this.nodes;
104	    const top = nodes[0];
105	    const last = nodes.pop();
106	    if (nodes.length > 0) {
107	      nodes[0] = last;
108	      let i = 0;
109	      for (;;) {
110	        const left = i * 2 + 1;
111	        const right = left + 1;
112	        let next = i;
113	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
114	          next = left;
115	        }
116	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
117	          next = right;
118	        }
119	        if (next === i) {
120	          break;
121	        }
122	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
123	        i = next;
124	      }
125	    }
126	    return top;
127	  }
128	}
