137	// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
138	// requests in deadline order instead of scanning every pending request, so
139	// a large waiting population costs O(expired * log n), never O(n) per call.
140	class DeadlineQueue {
141	  constructor() {
142	    this.nodes = [];
143	  }
144	
145	  get size() {
146	    return this.nodes.length;
147	  }
148	
149	  push(node) {
150	    const nodes = this.nodes;
151	    nodes.push(node);
152	    let i = nodes.length - 1;
153	    while (i > 0) {
154	      const parent = (i - 1) >> 1;
155	      if (deadlineBefore(nodes[i], nodes[parent])) {
156	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
157	        i = parent;
158	      } else {
159	        break;
160	      }
161	    }
162	  }
163	
164	  peek() {
165	    return this.nodes[0];
166	  }
167	
168	  pop() {
169	    const nodes = this.nodes;
170	    const top = nodes[0];
171	    const last = nodes.pop();
172	    if (nodes.length > 0) {
173	      nodes[0] = last;
174	      let i = 0;
175	      for (;;) {
176	        const left = i * 2 + 1;
177	        const right = left + 1;
178	        let next = i;
179	        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
180	          next = left;
181	        }
182	        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
183	          next = right;
184	        }
185	        if (next === i) {
186	          break;
187	        }
188	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
189	        i = next;
190	      }
191	    }
192	    return top;
193	  }
194	}
