206	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
207	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
208	    throw new TypeError('ttlMs must be a positive finite number');
209	  }
210	  if (typeof clock !== 'function') {
211	    throw new TypeError('clock must be a function');
212	  }
213	
214	  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
215	  const defaultTtlMs = ttlMs;
216	  // resource -> FIFO array of queue positions. A group request listing the
217	  // same resource in several rows occupies one position per row.
218	  const waitQueues = new Map();
219	  // requestId -> group, while the request is still queued.
220	  const pendingGroups = new Map();
221	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq, chain,
222	  // counted }
223	  const leases = new Map();
224	  // Every token this instance knows about, including replayed credentials
225	  // that were already released or reclaimed, so a freshly minted token can
226	  // never reuse a dead credential's string.
227	  const knownTokens = new Set();
228	  // resource -> Set of tokens currently attached to it. A share resource
229	  // usually carries several live credentials; the set makes release and
230	  // reclaim O(1) regardless of how many shares coexist.
231	  const slots = new Map();
232	  // resource -> runtime bookkeeping. Created lazily; an undeclared resource
233	  // is a capacity-1 resource with no quota chain.
234	  const resourceStates = new Map();
235	  // quota id -> { id, parentId, limit, live, heap, resources }. `live` is the
236	  // current share occupation counted against the limit, maintained per share
237	  // grant and released lazily by the quota's own expiry heap.
238	  const quotas = new Map();
239	  // The global expiry heap drives sweep(); resource and quota heaps drive
240	  // lazy, sub-linear availability checks.
241	  const expiryQueue = new ExpiryQueue();
242	  // One node per queued wait request, ordered by wait deadline. Nodes outlive
243	  // their request only until the next lazy pop, flagged `dead`.
244	  const deadlineQueue = new DeadlineQueue();
