253	  // Per-instance identity makes tokens unique across registries living in the
254	  // same process; one instance can never present a token another owns.
255	  registrySequence += 1;
256	  const registryId = registrySequence;
257	  let tokenSequence = 0;
258	  let queueOrder = 0;
259	  let deadlineTie = 0;
260	  let requestSequence = 0;
261	  let batchSequence = 0;
262	  // Monotonic id stamped on every persisted event; a snapshot records the
263	  // last id it folded in, so a log still containing the folded prefix (the
