import { createRegistry, LeaseFencedError } from './src/index.js';

let pass = 0, fail = 0;
function check(name, cond) { if (cond) pass++; else { fail++; console.log('FAIL:', name); } }

// --- in-memory basics ---
const c = { t: 0, now() { return this.t; } };
