check('unknown epoch is 0', r.epoch('x') === 0);
const a1 = r.acquire('r', 'a', 50);
check('first epoch 1', a1.epoch === 1 && r.epoch('r') === 1);
check('assert ok', r.assertLease('r', a1.token, 1) === true);

// failed contention does not burn epoch
try { r.acquire('r', 'b', 50); check('contention throws', false); } catch (e) { check('contention LeaseTaken', e.name === 'LeaseTakenError'); }
check('epoch stays 1 after failed acquire', r.epoch('r') === 1);

// same-holder retake after release -> epoch 2
check('release', r.release(a1.token) === true);
check('epoch stays 1 after release', r.epoch('r') === 1);
const a2 = r.acquire('r', 'a', 50);
check('retake epoch 2', a2.epoch === 2 && r.epoch('r') === 2);

// renew does not bump
check('renew', r.renew(a2.token) === true);
check('epoch stays 2 after renew', r.epoch('r') === 2);
check('assert after renew', r.assertLease('r', a2.token, 2) === true);

// old epoch fences
try { r.assertLease('r', a2.token, 1); check('old epoch fences', false); } catch (e) { check('old epoch LeaseFenced', e instanceof LeaseFencedError && e.code === 'LEASE_FENCED'); }
// old token fences
try { r.assertLease('r', a1.token, 2); check('old token fences', false); } catch (e) { check('old token LeaseFenced', e.code === 'LEASE_FENCED'); }
// unknown resource/token
try { r.assertLease('zzz', 't', 1); check('unknown resource fences', false); } catch (e) { check('unknown resource LeaseFenced', e.code === 'LEASE_FENCED'); }
try { r.assertLease('r', 'nope', 2); check('unknown token fences', false); } catch (e) { check('unknown token LeaseFenced', e.code === 'LEASE_FENCED'); }
// expired fences
c.t = 200;
try { r.assertLease('r', a2.token, 2); check('expired fences', false); } catch (e) { check('expired LeaseFenced', e.code === 'LEASE_FENCED'); }
check('epoch still 2 when no live lease', r.epoch('r') === 2);

// sweep then retake -> 3
const freed = r.sweep();
check('sweep freed r', JSON.stringify(freed) === JSON.stringify(['r']));
const a3 = r.acquire('r', 'c', 50);
check('after sweep epoch 3', a3.epoch === 3);

// TypeError shapes
for (const args of [[1, 't', 1], ['r', 2, 1], ['r', 't', 1.5], ['r', 't', NaN], ['r', 't', Infinity]]) {
  try { r.assertLease(...args); check('typeerror ' + JSON.stringify(args), false); } catch (e) { check('TypeError ' + JSON.stringify(args), e instanceof TypeError && !(e instanceof LeaseFencedError)); }
}
try { r.epoch(123); check('epoch typeerror', false); } catch (e) { check('epoch TypeError', e instanceof TypeError); }

console.log(pass, 'passed,', fail, 'failed');
process.exit(fail ? 1 : 0);
"

